249	
250	func (req IssueRequest) validatePresent() error {
251		missing := []string{}
252		if strings.TrimSpace(req.Operator) == "" {
253			missing = append(missing, "operator")
254		}
255		if strings.TrimSpace(req.Reason) == "" {
256			missing = append(missing, "reason")
257		}
258		if strings.TrimSpace(req.RequestID) == "" {
259			missing = append(missing, "request_id")
260		}
261		if strings.TrimSpace(req.ItemID) == "" {
262			missing = append(missing, "item_id")
263		}
264		if strings.TrimSpace(req.SeriesID) == "" {
265			missing = append(missing, "series_id")
266		}
267		if strings.TrimSpace(req.BatchNo) == "" {
268			missing = append(missing, "batch_no")
269		}
270		if strings.TrimSpace(req.HolderID) == "" {
271			missing = append(missing, "holder_id")
272		}
273		if len(missing) > 0 {
274			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
275		}
276		return nil
277	}
278	
279	func issueParamsSig(req IssueRequest) string {
280		b, _ := json.Marshal(struct {
281			Kind     string `json:"kind"`
282			ItemID   string `json:"item_id"`
283			SeriesID string `json:"series_id"`
284			BatchNo  string `json:"batch_no"`
285			Metadata string `json:"metadata"`
286			HolderID string `json:"holder_id"`
287			Reason   string `json:"reason"`
288		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
289		return string(b)
290	}
291	
292	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
293	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
294	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
295	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
296	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
297		if err := req.validatePresent(); err != nil {
298			return IssueResult{}, err
299		}
300		r.mu.Lock()
301		defer r.mu.Unlock()
302		if err := r.checkOpen(); err != nil {
303			return IssueResult{}, err
304		}
305	
306		key := requestKey(req.Operator, req.RequestID)
307		sig := issueParamsSig(req)
308		if prev, ok := r.state.Requests[key]; ok {
309			return r.replayIssue(prev, sig)
310		}
311	
312		bizErr := r.checkIssue(req)
313		if bizErr != nil {
314			if !isValidationErr(bizErr) {
315				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
316				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
317				r.state.Requests[key] = request{
318					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
319					Params: sig, Rejected: true, Reason: errCode(bizErr),
320					ItemID: req.ItemID,
321				}
322				_ = r.commit()
323			}
324			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
325			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
326		}
327	
328		seq := r.state.NextSeq + 1
329		r.state.NextSeq = seq
330		r.state.Items[req.ItemID] = item{
331			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
332			Metadata: req.Metadata, IssuedTxID: seq,
333		}
334		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
335		r.state.History = append(r.state.History, historyEntry{
336			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
337			Reason: req.Reason, RequestID: req.RequestID,
338			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
339		})
340		r.state.Requests[key] = request{
341			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
342			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
343		}
344		if err := r.commit(); err != nil {
345			return IssueResult{}, err
346		}
347		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
348	}
349	
350	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
351	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
352	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
353	func (r *Registry) checkIssue(req IssueRequest) error {
354		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
355	}
356	
357	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
358		if prev.Kind != "issue" || prev.Params != sig {
359			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
360				ErrRequestConflict, prev.Operator, prev.RequestID)
361		}
362		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
363			TxSeq: prev.TxSeq, Replayed: true}
364		if prev.Rejected {
365			res.Err = codeErr(prev.Reason)
366			return res, res.Err
367		}
368		return res, nil
369	}
370	
371	// ---- 转让 ----
372	
373	func (req TransferRequest) validatePresent() error {
374		missing := []string{}
375		if strings.TrimSpace(req.Operator) == "" {
376			missing = append(missing, "operator")
377		}
378		if strings.TrimSpace(req.Reason) == "" {
379			missing = append(missing, "reason")
380		}
381		if strings.TrimSpace(req.RequestID) == "" {
382			missing = append(missing, "request_id")
383		}
384		if strings.TrimSpace(req.ItemID) == "" {
385			missing = append(missing, "item_id")
386		}
387		if strings.TrimSpace(req.ExpectedOwner) == "" {
388			missing = append(missing, "expected_owner")
389		}
390		if strings.TrimSpace(req.ToID) == "" {
391			missing = append(missing, "to_id")
392		}
393		if req.ExpectedVer <= 0 {
394			missing = append(missing, "expected_version")
395		}
396		if len(missing) > 0 {
397			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
398		}
399		if req.Price < 0 {
400			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
401		}
402		return nil
403	}
404	
405	func transferParamsSig(req TransferRequest) string {
406		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
407		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
408		// 冲突拒绝。
409		b, _ := json.Marshal(struct {
410			Kind          string `json:"kind"`
411			ItemID        string `json:"item_id"`
412			ExpectedOwner string `json:"expected_owner"`
413			ExpectedVer   int64  `json:"expected_version"`
414			ToID          string `json:"to_id"`
415			Price         int64  `json:"price,omitempty"`
416			Reason        string `json:"reason"`
417		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
418		return string(b)
419	}
420	
421	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
422	// 各自的返回结构与请求记录。
423	type transferOutcome struct {
424		seq     int64      // 转让历史序号
425		fromID  string     // 转让前持有人
426		fromVer int64      // 转让前持有版本
427		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
428	}
429	
430	// toVer 是转让后的持有版本。
431	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
432	
433	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
434	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
435	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
436	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
437	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
438	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
439		h := r.state.Holdings[itemID]
440		seq := r.state.NextSeq + 1
441		r.state.NextSeq = seq
442		from := h.OwnerID
443		fromVer := h.Version
444		h.OwnerID = toID
445		h.Version = fromVer + 1
446		r.state.Holdings[itemID] = h
447		r.state.History = append(r.state.History, historyEntry{
448			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
449			Reason: reason, RequestID: requestID,
450			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
451			AuthID: authID,
452		})
453		// 版税按所属系列的规则快照计算；余款归转让前持有人。
454		it := r.state.Items[itemID]
455		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
456			r.state.Series[it.SeriesID].Royalty, from)
457		r.state.Royalties[seq] = royalty
458		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
459	}
460	
461	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
462	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
463	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
464	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
465	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
466	// 请求重复提交（即使藏品后来已易手）返回首次结果。
467	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
468		if err := req.validatePresent(); err != nil {
469			return TransferResult{}, err
470		}
471		r.mu.Lock()
472		defer r.mu.Unlock()
473		if err := r.checkOpen(); err != nil {
474			return TransferResult{}, err
475		}
476	
477		key := requestKey(req.Operator, req.RequestID)
478		sig := transferParamsSig(req)
479		if prev, ok := r.state.Requests[key]; ok {
480			return r.replayTransfer(prev, sig)
481		}
482	
483		bizErr := r.checkTransfer(req)
484		if bizErr != nil {
485			if !isValidationErr(bizErr) {
486				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
487				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
488				r.state.Requests[key] = request{
489					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
490					Params: sig, Rejected: true, Reason: errCode(bizErr),
491					ItemID: req.ItemID,
492				}
493				_ = r.commit()
494			}
495			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
496			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
497		}
498	
499		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
500		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
501		r.state.Requests[key] = request{
502			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
503			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
504			Version: out.toVer(), TxSeq: out.seq,
505		}
506		if err := r.commit(); err != nil {
507			return TransferResult{}, err
508		}
509		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
510			Version: out.toVer(), TxSeq: out.seq,
511			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
512			Remainder: out.royalty.Remainder}, nil
513	}
514	
515	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
516	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
517	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
518	// 于持有信息不符。
519	func (r *Registry) checkTransfer(req TransferRequest) error {
520		return r.checkSingleTransferEligibility(directTransferEligibility{
521			itemID:        req.ItemID,
522			operator:      req.Operator,
523			toID:          req.ToID,
524			expectedOwner: req.ExpectedOwner,
525			expectedVer:   req.ExpectedVer,
526		})
527	}
528	
529	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
530		if prev.Kind != "transfer" || prev.Params != sig {
531			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
532				ErrRequestConflict, prev.Operator, prev.RequestID)
533		}
534		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
535			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
536		if prev.Rejected {
537			res.Err = codeErr(prev.Reason)
538			return res, res.Err
539		}
540		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
541		// 价款与应付明细，不重复计入。
542		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
543		return res, nil
544	}
545	
546	// ---- 限时一次性代转授权 ----
547	
548	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
549	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
550	func authzCurrentStatus(a authzRec, now time.Time) string {
551		switch a.Status {
552		case "revoked":
553			return AuthRevoked
554		case "used":
555			return AuthUsed
556		}
557		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
558			return AuthExpired
559		}
560		return AuthActive
561	}
