    if !isValidationErr(bizErr) {
        r.state.Requests[key] = request{...}
        if err := r.commit(); err != nil {
            // 保存失败：拒绝结果没有记住，请求号不占用，返回保存错误
            return TransferBatchResult{}, err
        }
